files.examples/01_deadlock.sql:
-- Two transfers at once: A moves 10 from a to b, B moves 20 from b to a.
-- Each locks its source row first.
A: BEGIN;
B: BEGIN;
A: UPDATE accounts SET balance = balance - 10 WHERE id = 'a';
B: UPDATE accounts SET balance = balance - 20 WHERE id = 'b';

-- Each now needs the row the other holds.
A: UPDATE accounts SET balance = balance + 10 WHERE id = 'b';
B: UPDATE accounts SET balance = balance + 20 WHERE id = 'a';

-- After deadlock_timeout (1 s) the detector finds the cycle and aborts one
-- transaction. The other one's update goes through.
A: ROLLBACK;
B: COMMIT;
A: SELECT id, balance FROM accounts ORDER BY id;

files.examples/02_lock_ordering.sql:
-- The same two transfers. Each first locks BOTH rows, in key order,
-- whichever direction the money flows.
A: BEGIN;
B: BEGIN;
A: SELECT id FROM accounts WHERE id IN ('a', 'b') ORDER BY id FOR NO KEY UPDATE;
B: SELECT id FROM accounts WHERE id IN ('a', 'b') ORDER BY id FOR NO KEY UPDATE;

-- B waits for row a while holding nothing, so no cycle can form.
A: UPDATE accounts SET balance = balance - 10 WHERE id = 'a';
A: UPDATE accounts SET balance = balance + 10 WHERE id = 'b';
A: COMMIT;

B: UPDATE accounts SET balance = balance - 20 WHERE id = 'b';
B: UPDATE accounts SET balance = balance + 20 WHERE id = 'a';
B: COMMIT;
B: SELECT id, balance FROM accounts ORDER BY id;

files.examples/03_advisory.sql:
-- Advisory locks lock a number, not a row. 4242 means "the nightly report"
-- here; the database doesn't know or care.

-- Transaction-level: released by COMMIT or ROLLBACK, like a row lock.
A: BEGIN;
A: SELECT pg_try_advisory_xact_lock(4242) AS got_it;
B: SELECT pg_try_advisory_xact_lock(4242) AS got_it;
A: COMMIT;
B: SELECT pg_try_advisory_xact_lock(4242) AS got_it;

-- Session-level: held until unlocked or the connection closes,
-- and transactions don't touch it.
A: BEGIN;
A: SELECT pg_try_advisory_lock(4242) AS got_it;
A: ROLLBACK;
B: SELECT pg_try_advisory_lock(4242) AS got_it;
A: SELECT pg_advisory_unlock(4242) AS released;
B: SELECT pg_try_advisory_lock(4242) AS got_it;
B: SELECT pg_advisory_unlock(4242) AS released;
